package com.example.lms.content;
import javax.imageio.*; import java.awt.*; import java.awt.image.*; import java.io.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class ImageProcessingService {
 public record ProcessedImage(String name,String contentType,byte[] data){}
 public ProcessedImage normalize(MultipartFile file) throws IOException {BufferedImage source=ImageIO.read(file.getInputStream());if(source==null)throw new IllegalArgumentException("Unsupported image. Use the crop tool to convert browser-readable images to JPEG, or upload a JPEG, PNG, GIF, or BMP image.");String original=java.util.Optional.ofNullable(file.getOriginalFilename()).orElse("image");if(original.toLowerCase().endsWith(".gif")&&"image/gif".equalsIgnoreCase(file.getContentType()))return new ProcessedImage(original,"image/gif",file.getBytes());int max=1920;double scale=Math.min(1d,(double)max/Math.max(source.getWidth(),source.getHeight()));int width=Math.max(1,(int)Math.round(source.getWidth()*scale)),height=Math.max(1,(int)Math.round(source.getHeight()*scale));BufferedImage output=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);Graphics2D g=output.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,width,height);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);g.setRenderingHint(RenderingHints.KEY_RENDERING,RenderingHints.VALUE_RENDER_QUALITY);g.drawImage(source,0,0,width,height,null);g.dispose();ByteArrayOutputStream bytes=new ByteArrayOutputStream();ImageIO.write(output,"jpg",bytes);String base=original.replaceFirst("\\.[^.]+$","");return new ProcessedImage(base+".jpg","image/jpeg",bytes.toByteArray());}
}
